use kimo_core::color::cct_grade::map;
#[test]fn formula_known_and_inverse(){assert_eq!(map(0.,0.1,1.,1.,0.,false),0.1);assert_eq!(map(1.,0.1,1.,2.,0.05,false),2.05);assert!((map(0.25,0.,2.,1.,0.,false)-0.5).abs()<1e-14);for x in [-0.1,0.,0.072905534,0.15525114,0.4135884,1.,2.]{let y=map(x,-0.02,1.1,1.03,0.01,false);assert!((map(y,-0.02,1.1,1.03,0.01,true)-x).abs()<1e-12);}}
#[cfg(feature="native-ocio")]
mod native{
use kimo_core::{effects::{Frame,Params},color::{cct_grade,ocio_config::Config},keyframe::Prop,commands::{Session,dispatch}};use serde_json::json;
fn strings()->std::collections::BTreeMap<String,String>{[("config_path",concat!(env!("CARGO_MANIFEST_DIR"),"/tests/data/minimal_aces.ocio")),("linear_space","ACEScg"),("cct_space","ACEScct")].into_iter().map(|(k,v)|(k.into(),v.into())).collect()}
fn params()->Params{[("lift_r",0.01),("lift_g",-0.01),("gamma_r",1.04),("gamma_g",1.02),("gain_r",1.02),("offset_b",0.005)].into_iter().map(|(k,v)|(k.into(),Prop::new(v))).collect()}
#[test]fn real_ocio_reference_math_inverse_determinism(){let s=strings();let mut f=Frame{w:2,h:1,d:vec![-0.01,0.,0.0078125,0.5,0.18,1.,4.,1.]};let orig=f.d.clone();let p=params();cct_grade::apply(&p,&s,&mut f,0.).unwrap();let mut reference=Frame{w:2,h:1,d:orig.clone()};let c=Config::from_file(&s["config_path"]).unwrap();c.processor("ACEScg","ACEScct").unwrap().apply(&mut reference).unwrap();for px in reference.d.chunks_exact_mut(4){for(j,(l,g,a,o))in [(0.01,1.04,1.02,0.),(-0.01,1.02,1.,0.),(0.,1.,1.,0.005)].iter().enumerate(){let x=px[j] as f64;px[j]=((x+l*(1.-x)).abs().powf(1./g).copysign(x+l*(1.-x))*a+o) as f32;}}c.processor("ACEScct","ACEScg").unwrap().apply(&mut reference).unwrap();for(a,b)in reference.d.iter().zip(&f.d){assert!((*a-*b).abs()<2e-6);}let out=f.d.clone();for _ in 0..8{let mut a=Frame{w:2,h:1,d:orig.clone()};cct_grade::apply(&p,&s,&mut a,0.).unwrap();assert_eq!(a.d,out);}let mut inv=p;inv.insert("inverse".into(),Prop::new(1.));cct_grade::apply(&inv,&s,&mut f,0.).unwrap();for(i,(a,b))in f.d.iter().zip(orig).enumerate(){if i%4==3{assert_eq!(*a,b)}else{assert!((*a-b).abs()<2e-5);}}}
#[test]fn identity_bitexact_and_bad_atomic(){let mut f=Frame{w:1,h:1,d:vec![-0.,4.,-0.1,0.3]};let b=f.d.iter().map(|v|v.to_bits()).collect::<Vec<_>>();cct_grade::apply(&Params::new(),&strings(),&mut f,0.).unwrap();assert_eq!(b,f.d.iter().map(|v|v.to_bits()).collect::<Vec<_>>());for(k,v)in[("gamma_r",0.),("lift_r",1.),("gain_b",0.),("inverse",2.)]{let mut p=Params::new();p.insert(k.into(),Prop::new(v));assert!(cct_grade::apply(&p,&strings(),&mut f,0.).is_err());assert_eq!(b,f.d.iter().map(|v|v.to_bits()).collect::<Vec<_>>());}}
#[test]fn mcp_bound_domain_and_unknownparam(){let mut s=Session::new();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let id=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","color":[0.18,0.18,0.18],"start":0,"duration":1})).unwrap()["clip_id"].clone();let a=json!({"clip_id":id,"config_path":strings()["config_path"],"linear_space":"ACEScg","cct_space":"ACEScct","params":{"gamma_r":1.02}});assert!(dispatch(&mut s,"add_acescct_primaries",&a).is_err());dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"working_gamut":3}})).unwrap();dispatch(&mut s,"add_acescct_primaries",&a).unwrap();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"working_gamut":0}})).unwrap();assert!(kimo_core::render::render_frame(&s.project,0.4,&s.cache).is_err());}
}

#[cfg(feature="native-ocio")]
#[test]fn wrapper_conflicts_fail_before_domain_transform(){use kimo_core::effects::{Frame,Params,apply};let mut f=Frame{w:1,h:1,d:vec![0.18,0.18,0.18,1.]};for key in ["ocio_domain","wrapper_working_gamut"]{let s=[(key.into(),"3".into())].into_iter().collect();let before=f.d.clone();assert!(apply("acescct_primaries",&Params::new(),&s,&mut f,0.,0).unwrap_err().contains("no extra wrapper"));assert_eq!(before,f.d);}}
